function M.sub(a, b)
    return a - b
end

function M.mul(a, b)
    return a * b
end

function M.div(a, b)
    if b == 0 then
        error("Cannot divide by zero")
    end
    return a / b
end

function M.min(a, b)
    return math.min(a, b)
end

function M.max(a, b)
    return math.max(a, b)
end
